import assert from "node:assert/strict";
import {createRequire} from "node:module";
import {readFile} from "node:fs/promises";
import {PostgresDecisionLedger} from "../postgres-ledger.mjs";
import {authorizeDecision,consumeAuthorization,reconcileAuthorization} from "../ledger.mjs";
import {fixture} from "./fixture.mjs";
const require=createRequire(process.env.MI_TEST_PG_PACKAGE+"/package.json"),{Pool}=require("pg");
const url=new URL(process.env.MI_TEST_DATABASE_URL);assert.equal(url.hostname,"127.0.0.1");assert.notEqual(url.port,"5432");assert.ok(url.pathname.startsWith("/seg0_"));assert.equal(process.env.SPHERIO_DISPOSABLE_TEST_DATABASE,"1");
const pool=new Pool({connectionString:url.toString(),max:12});
try {await pool.query(await readFile(new URL("../schema.sql",import.meta.url),"utf8"));const f=fixture(),now=Date.parse("2026-10-12T12:00:00Z");for(const item of Object.values(f.state.evidence))item.observedAt="2026-10-12T11:59:59.123456789Z";f.intent.operation="transfer";f.intent.quantityBaseUnits="100";
 const begin=performance.now();const results=await Promise.all(Array.from({length:12},(_,i)=>{const idempotencyKey="race-"+i;return authorizeDecision({ledger:new PostgresDecisionLedger(pool,{...f.intent,idempotencyKey}),policy:f.policy,intent:{...f.intent,product:["Pump","Prime","RioLight"][i%3]},idempotencyKey,now,loadCanonical:async()=>structuredClone(f.state)});}));
 assert.equal(results.filter(r=>r.executionAllowed).length,6);const rows=await pool.query("SELECT count(*)::int n FROM mi_decision_events");assert.equal(rows.rows[0].n,12);const first=results.find(r=>r.executionAllowed),ledger=new PostgresDecisionLedger(pool,{...f.intent,authorizationId:first.authorizationId});
 await consumeAuthorization(ledger,first.authorizationId,first.intentDigest,async()=>true,()=>now);await assert.rejects(()=>consumeAuthorization(ledger,first.authorizationId,first.intentDigest,async()=>true));
 await assert.rejects(()=>pool.query("UPDATE mi_decision_events SET event_type='tampered'"),/append-only/);await assert.rejects(()=>pool.query("DELETE FROM mi_decision_events"),/append-only/);
 await reconcileAuthorization(ledger,first.authorizationId,{verified:true,chainId:f.intent.chainId,intentDigest:first.intentDigest,txHash:"A".repeat(64),height:"2",blockHash:"block2",reference:"fixture-tx-proof",code:0});
 const late=await authorizeDecision({ledger:new PostgresDecisionLedger(pool,{...f.intent,idempotencyKey:"lagged"}),policy:f.policy,intent:f.intent,idempotencyKey:"lagged",now,loadCanonical:async()=>structuredClone(f.state)});assert.equal(late.executionAllowed,false);
 const replay=await authorizeDecision({ledger:new PostgresDecisionLedger(pool,{...f.intent,idempotencyKey:first.idempotencyKey}),policy:f.policy,intent:first.intent,idempotencyKey:first.idempotencyKey,now,loadCanonical:async()=>structuredClone(f.state)});assert.equal(replay.authorizationId,first.authorizationId);
 await assert.rejects(()=>ledger.atomic(async()=>{throw Error("fixture-rollback");}),/fixture-rollback/);assert.equal((await pool.query("SELECT count(*)::int n FROM pg_locks WHERE locktype='advisory' AND granted")).rows[0].n,0,"session locks must be released after success and rollback");
 const laterTime=now+61000;const advanced=structuredClone(f.state);advanced.holdingsBaseUnits="500";for(const e of Object.values(advanced.evidence)){e.observedAt=new Date(laterTime).toISOString();e.height="2";e.blockHash="block2";}for(const w of advanced.velocity){w.asOf=laterTime;w.completeSince=laterTime-w.seconds*1000;w.executedBaseUnits="100";}
 const recovered=await authorizeDecision({ledger:new PostgresDecisionLedger(pool,{...f.intent,idempotencyKey:"after-expiry"}),policy:f.policy,intent:f.intent,idempotencyKey:"after-expiry",now:laterTime,loadCanonical:async()=>advanced});assert.equal(recovered.executionAllowed,true);assert.equal((await pool.query("SELECT count(*)::int n FROM mi_decisions WHERE status='EXPIRED'")).rows[0].n,5);assert.equal((await pool.query("SELECT status FROM mi_decisions WHERE authorization_id=$1",[first.authorizationId])).rows[0].status,"CONFIRMED");
 console.log(JSON.stringify({fixtureOnly:true,concurrentRequests:12,accepted:6,rejected:6,elapsedMs:performance.now()-begin,checks:["serializable-cross-product-reservation","replay","audit-immutability","confirmed-index-lag","idempotency","expiry-capacity-recovery","confirmed-execution-retained"],productionChanges:false}));
}finally{await pool.end();}
